package com.example.starter.cue.support;

import java.time.Clock;
import java.time.LocalDateTime;
import java.time.ZoneId;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 时间与基础 Bean 配置；业务代码统一通过注入的 {@link Clock} 取当前时间，测试可替换为固定时钟。
 */
@Configuration
public class ClockConfig {

    /**
     * 业务时区固定为 Asia/Shanghai，时间列均按此时区记录本地时间。
     */
    public static final ZoneId BUSINESS_ZONE = ZoneId.of("Asia/Shanghai");

    /**
     * 系统时钟；测试中可用 {@link Clock#fixed} 覆盖。
     */
    @Bean
    public Clock businessClock() {
        return Clock.system(BUSINESS_ZONE);
    }

    /**
     * 按业务时区取当前本地时间。
     */
    public static LocalDateTime now(Clock clock) {
        return LocalDateTime.now(clock.withZone(BUSINESS_ZONE));
    }
}

package com.example.starter.cue.exception;

/**
 * 资源不存在，映射 HTTP 404。
 */
public class CueNotFoundException extends RuntimeException {

    public CueNotFoundException(String message) {
        super(message);
    }
}

package com.example.starter.cue.exception;

/**
 * 请求与当前业务状态冲突（跳号回报、异参重放、并发下序号已推进等），映射 HTTP 409。
 */
public class CueConflictException extends RuntimeException {

    public CueConflictException(String message) {
        super(message);
    }
}

package com.example.starter.cue.exception;

import java.util.List;

/**
 * 提示点编排或冻结参数非法（时长越界、序号重复/不连续等），映射 HTTP 400。
 * 整版本校验失败时携带全部错误原因，调用方不得只丢弃部分坏提示点。
 */
public class CueValidationException extends RuntimeException {

    private final List<String> errors;

    public CueValidationException(List<String> errors) {
        super(String.join("; ", errors));
        this.errors = List.copyOf(errors);
    }

    public List<String> getErrors() {
        return errors;
    }
}

