        assertThat(badDuration.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);

        ResponseEntity<String> duplicateSeq = rest.postForEntity("/api/cue-versions",
                new CreateVersionRequest(PLAY, List.of(
