        assertThat(duplicateSeq.getStatusCode()).isEqualTo(HttpStatus.BAD_REQUEST);

        // 失败后不允许残留半截版本或提示点
        Integer versionCount = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM cue_version WHERE play_code = '" + PLAY + "'", Integer.class);
