        assertThat(frozenDetail.frozenSequence()).hasSize(2);
        assertThat(frozenDetail.frozenSequence().get(0).triggerWord()).isEqualTo("旧口令");
        assertThat(frozenDetail.frozenSequence().get(0).durationSeconds()).isEqualTo(10);
